//! Parity and regression tests for the arktts (Audio8 TTS) family.
//!
//! Pinned fixtures reside in `testdata/tts_arktts/`, generated by
//! `tools/gen_arktts_fixtures.py` against mlx-audio commit
//! `e1b19b9054bf163f5d812221a54fcc346f1890e9` (mlx 0.32.3) on the CPU
//! device. The generator runs the true reference module (tiny seeded codec
//! subclasses stand in for the hardcoded widths; a word-level
//! PreTrainedTokenizerFast stands in for the network Mistral tokenizer),
//! so the traces carry the prompt segment ids, the greedy and sampled
//! `generate_codes` grids, the recorded uniform stream for the exponential
//! race, the reference-voice path with recorded codec `encode` codes, the
//! decode-stage traces, and the sampler math on fixed logits.

use std::path::{Path, PathBuf};

use serde_json::Value;

use super::{
    codec, legacy_top_k_top_p, prepare_prompt, prompt_segments, sample_semantic, Model,
    ModelConfig, SamplingParams, Uniforms,
};
use crate::lm::Weights;

fn testdata(name: &str) -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR"))
        .join("testdata/tts_arktts")
        .join(name)
}

fn read_json(path: &Path) -> Value {
    let text = std::fs::read_to_string(path).expect("fixture json");
    serde_json::from_str(&text).expect("fixture json")
}

fn i32_vec(value: &Value) -> Vec<i32> {
    value
        .as_array()
        .expect("ids")
        .iter()
        .map(|v| v.as_i64().expect("id") as i32)
        .collect()
}

fn i32_rows(value: &Value) -> Vec<Vec<i32>> {
    value
        .as_array()
        .expect("rows")
        .iter()
        .map(i32_vec)
        .collect()
}

fn f32_vec(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| v.as_f64().expect("value") as f32)
        .collect()
}

/// Filtered sampler outputs use null for the reference's negative
/// infinities (strict JSON cannot carry them).
fn f32_vec_masked(value: &Value) -> Vec<f32> {
    value
        .as_array()
        .expect("values")
        .iter()
        .map(|v| {
            if v.is_null() {
                f32::NEG_INFINITY
            } else {
                v.as_f64().expect("value") as f32
            }
        })
        .collect()
}

fn max_abs_diff(a: &[f32], b: &[f32]) -> f32 {
    assert_eq!(
        a.len(),
        b.len(),
        "length mismatch: {} vs {}",
        a.len(),
        b.len()
    );
    a.iter()
        .zip(b)
        .map(|(x, y)| (x - y).abs())
        .fold(0.0f32, f32::max)
}

/// The kept-set pattern of a filtered score vector (which entries survive
/// the -inf masking) must match exactly; the kept values ride a tolerance.
fn assert_kept_pattern_and_values(got: &[f32], want: &[f32], tolerance: f32, what: &str) {
    assert_eq!(got.len(), want.len(), "{what} width");
    let mut diff = 0.0f32;
    for (index, (&g, &w)) in got.iter().zip(want).enumerate() {
        match (g.is_finite(), w.is_finite()) {
            (true, true) => diff = diff.max((g - w).abs()),
            (false, false) => {}
            _ => panic!("{what}: entry {index} keep pattern diverged: {g} vs {w}"),
        }
    }
    assert!(diff <= tolerance, "{what}: kept value diff {diff}");
}

/// Asserts the slice is finite everywhere (the fixture gates propagate
/// NaN, so this pins the whole pipeline at once).
fn assert_finite(values: &[f32], what: &str) {
    assert!(
        values.iter().all(|v| v.is_finite()),
        "{what} carries a non-finite value"
    );
}

/// Measured maximum differences against the fixture traces when the gates
/// were frozen; assertions use these values, not re-measured ones. The
/// rope tables reproduce the reference's bf16 rounding exactly, so the
/// stage traces measured 3e-8 (from_codes, pure matvecs), 2.4e-6 (post
/// transformer accumulation order) and 3.3e-6 (upsample chain); the codec
/// decode waveforms measured 2.1e-6 and the end-to-end generation
/// waveforms 2.8e-6 across all four generation cases. The greedy codes
/// are int-exact by construction (the seed searches enforce decision
/// margins well above the float noise).
const STAGE_FROM_CODES_TOLERANCE: f32 = 1e-6;
const STAGE_POST_TOLERANCE: f32 = 1e-5;
const STAGE_UPSAMPLE_TOLERANCE: f32 = 1e-5;
const WAVEFORM_TOLERANCE: f32 = 1e-5;
const SAMPLER_TOLERANCE: f32 = 1e-5;

fn open_model(name: &str) -> Model {
    Model::open(&testdata(name)).expect("family model loads")
}

fn open_codec(name: &str) -> codec::ArkttsCodec {
    let weights = Weights::open(&testdata(name)).expect("weights open");
    let config_value = weights.config().clone();
    codec::ArkttsCodec::load(
        &weights,
        &codec::CodecConfig::from_tts_config(&config_value),
    )
    .expect("codec loads")
}

fn sampling_params(traces: &Value) -> SamplingParams {
    SamplingParams {
        max_new_tokens: traces["max_new_tokens"].as_u64().expect("max") as usize,
        temperature: traces["temperature"].as_f64().expect("temp") as f32,
        top_p: traces["top_p"].as_f64().expect("top_p") as f32,
        top_k: traces["top_k"].as_u64().expect("top_k") as usize,
        do_sample: traces["do_sample"].as_bool().expect("do_sample"),
    }
}

/// Transposes the frame-major generation grid into the book-major rows the
/// codec consumes (the reference decodes `(B, num_codebooks, T)`).
fn book_major(codes: &[Vec<i32>], num_codebooks: usize) -> Vec<Vec<i32>> {
    let frames = codes.len();
    let mut rows = vec![Vec::with_capacity(frames); num_codebooks];
    for row in codes {
        for (book, &code) in row.iter().enumerate() {
            rows[book].push(code);
        }
    }
    rows
}

fn run_generation(model: &mut Model, traces: &Value) -> Vec<Vec<i32>> {
    let prefix = i32_vec(&traces["prefix_ids"]);
    let suffix = i32_vec(&traces["suffix_ids"]);
    let params = sampling_params(traces);
    let generation = model
        .model
        .generate_codes(&prefix, &suffix, None, 0, &params, 0)
        .expect("generate codes");
    generation.codes
}

#[test]
fn config_defaults_match_the_reference_dataclass() {
    // The reference ModelConfig defaults a fixture checkpoint never sets.
    let defaults = ModelConfig::from_json(&serde_json::json!({})).expect("defaults parse");
    assert_eq!(defaults.slow_backbone, "arktts");
    assert_eq!(defaults.vocab_size, 155_776);
    assert_eq!(defaults.dim, 896);
    assert_eq!(defaults.n_layer, 24);
    assert_eq!(defaults.n_head, 14);
    assert_eq!(defaults.n_local_heads, 2);
    assert_eq!(defaults.head_dim, 64);
    assert_eq!(defaults.rope_base, 1_000_000.0);
    assert!(defaults.attention_qkv_bias);
    assert!(!defaults.attention_qk_norm);
    assert!(!defaults.attention_o_bias);
    assert!(defaults.tie_word_embeddings);
    assert_eq!(defaults.codebook_size, 4096);
    assert_eq!(defaults.num_codebooks, 10);
    assert_eq!(defaults.semantic_begin_id, 151_678);
    assert_eq!(defaults.semantic_end_id, 155_773);
    assert_eq!(defaults.n_fast_layer, 4);
    assert!(defaults.norm_fastlayer_input);
    assert_eq!(defaults.ras_window_size, 10);
    assert!((defaults.ras_top_p - 0.9).abs() < 1e-6);
    assert_eq!(defaults.eos_token_id, 151_645);
    assert_eq!(defaults.pad_token_id, 151_643);
    assert_eq!(defaults.sample_rate, 44_100);
    assert!(!defaults.uses_falcon_slow());
    // The codec geometry rides the same config with the published defaults.
    let codec = codec::CodecConfig::from_tts_config(&serde_json::json!({}));
    assert_eq!(codec.hidden, 1024);
    assert_eq!(codec.quantizer_input_dim, 1024);
    assert_eq!(codec.decoder_channels, 1536);
    assert_eq!(codec.upsample_strides, vec![8, 8, 4, 2]);
    assert_eq!(codec.semantic_codebook_size, 4096);
    assert_eq!(codec.residual_books, 9);
    assert_eq!(codec.residual_codebook_size, 1024);
    assert_eq!(codec.codebook_dim, 8);
    assert_eq!(codec.post_n_layer, 8);
    assert_eq!(codec.post_n_head, 16);
    assert_eq!(codec.post_n_local_heads, 8);
    assert_eq!(codec.post_intermediate_size, 1216);
    // The falcon selection key.
    let falcon =
        ModelConfig::from_json(&serde_json::json!({"slow_backbone": "falcon_h1"})).expect("parses");
    assert!(falcon.uses_falcon_slow());
}

#[test]
fn codec_decode_matches_the_reference_stage_traces() {
    let traces = read_json(&testdata("codec/traces.json"));
    let codec = open_codec("codec");
    let codes = i32_rows(&traces["codes"]);
    let (from_codes, post, upsample) = codec.decode_stages(&codes).expect("stages run");
    assert_finite(&from_codes, "from_codes");
    assert_finite(&post, "post_module");
    assert_finite(&upsample, "upsample");

    let want_from_codes = f32_vec(&traces["from_codes"]);
    let diff = max_abs_diff(&from_codes, &want_from_codes);
    assert!(diff <= STAGE_FROM_CODES_TOLERANCE, "from_codes diff {diff}");

    let want_post = f32_vec(&traces["post_module"]);
    let diff = max_abs_diff(&post, &want_post);
    assert!(diff <= STAGE_POST_TOLERANCE, "post module diff {diff}");

    let want_up = f32_vec(&traces["upsample"]);
    let diff = max_abs_diff(&upsample, &want_up);
    assert!(diff <= STAGE_UPSAMPLE_TOLERANCE, "upsample diff {diff}");
}

#[test]
fn codec_decode_matches_the_reference_waveform_and_clamps() {
    let traces = read_json(&testdata("codec/traces.json"));
    let codec = open_codec("codec");
    let codes = i32_rows(&traces["codes"]);
    let got = codec.decode(&codes).expect("decodes");
    assert_finite(&got, "waveform");
    let want = f32_vec(&traces["waveform"]);
    assert_eq!(got.len(), want.len());
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "codec decode diff {diff}");

    // One over-range code per book clamps to the top bin on both sides.
    let clamped = i32_rows(&traces["clamped_codes"]);
    let got = codec.decode(&clamped).expect("clamped decodes");
    let want = f32_vec(&traces["clamped_waveform"]);
    let diff = max_abs_diff(&got, &want);
    assert!(diff <= WAVEFORM_TOLERANCE, "clamped decode diff {diff}");
}

#[test]
fn codec_decode_refuses_a_book_count_mismatch() {
    let codec = open_codec("codec");
    let error = codec.decode(&[vec![1, 2], vec![3, 4]]).unwrap_err();
    assert!(error.to_string().contains("codebook rows"), "{error}");
    let error = codec
        .decode(&[vec![1, 2], vec![3, 4], vec![5, 6], vec![7, 8]])
        .unwrap_err();
    assert!(error.to_string().contains("codebook rows"), "{error}");
}

#[test]
fn greedy_generation_matches_the_reference_pure_attention() {
    let traces = read_json(&testdata("pure_attention/traces.json"));
    let mut model = open_model("pure_attention");
    // The prompt builder parity rides the same load: the segment strings
    // are checked in prompt_building_matches_the_reference.
    let got = run_generation(&mut model, &traces);
    assert_eq!(got, i32_rows(&traces["codes"]), "generated codes");

    let prefix = i32_vec(&traces["prefix_ids"]);
    let suffix = i32_vec(&traces["suffix_ids"]);
    let params = sampling_params(&traces);
    let waveform = model
        .generate(&prefix, &suffix, None, 0, &params, 0)
        .expect("generate runs");
    assert_finite(&waveform, "generate waveform");
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(waveform.len(), want_wave.len());
    let diff = max_abs_diff(&waveform, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "generate waveform diff {diff}");

    // The book-major trace rows are the transpose of the frame-major codes.
    let book_major = i32_rows(&traces["codes_book_major"]);
    for (frame, row) in got.iter().enumerate() {
        for (book, &code) in row.iter().enumerate() {
            assert_eq!(code, book_major[book][frame], "transpose frame {frame}");
        }
    }
}

#[test]
fn sampled_generation_replays_the_recorded_uniform_stream() {
    let traces = read_json(&testdata("sampled/traces.json"));
    let mut model = open_model("sampled");
    let prefix = i32_vec(&traces["prefix_ids"]);
    let suffix = i32_vec(&traces["suffix_ids"]);
    let params = sampling_params(&traces);
    assert!(params.do_sample, "the sampled fixture must sample");

    let mut uniforms = Uniforms::new(0);
    for draw in traces["uniform_draws"].as_array().expect("draws") {
        uniforms.push(&f32_vec(draw));
    }
    let generation = model
        .model
        .generate_codes_with_uniforms(&prefix, &suffix, None, 0, &params, &mut uniforms)
        .expect("generate codes");
    assert_eq!(
        generation.codes,
        i32_rows(&traces["codes"]),
        "sampled codes under the recorded stream"
    );

    let waveform = model
        .codec
        .decode(&book_major(&generation.codes, model.config.num_codebooks))
        .expect("decodes");
    let want_wave = f32_vec(&traces["waveform"]);
    assert_eq!(waveform.len(), want_wave.len());
    let diff = max_abs_diff(&waveform, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "sampled waveform diff {diff}");
}

#[test]
fn voice_generation_rides_the_reference_codes() {
    let traces = read_json(&testdata("voice/traces.json"));
    let mut model = open_model("voice");
    let prefix = i32_vec(&traces["prefix_ids"]);
    let suffix = i32_vec(&traces["suffix_ids"]);
    let reference_codes = i32_rows(&traces["reference_codes"]);
    let reference_length = traces["reference_length"].as_u64().expect("length") as usize;
    let params = sampling_params(&traces);
    let generation = model
        .model
        .generate_codes(
            &prefix,
            &suffix,
            Some(&reference_codes),
            reference_length,
            &params,
            0,
        )
        .expect("generate codes");
    assert_eq!(
        generation.codes,
        i32_rows(&traces["codes"]),
        "voice codes with the reference prompt"
    );
    let waveform = model
        .codec
        .decode(&book_major(&generation.codes, model.config.num_codebooks))
        .expect("decodes");
    let want_wave = f32_vec(&traces["waveform"]);
    let diff = max_abs_diff(&waveform, &want_wave);
    assert!(diff <= WAVEFORM_TOLERANCE, "voice waveform diff {diff}");
}

