#[test]
fn eos_first_pick_cases_stop_with_no_frames() {
    for name in ["eos", "falcon_eos"] {
        let traces = read_json(&testdata(format!("{name}/traces.json").as_str()));
        let mut model = open_model(name);
        let generation = run_generation(&mut model, &traces);
        assert!(generation.is_empty(), "{name} must emit no frames");
        let prefix = i32_vec(&traces["prefix_ids"]);
        let params = sampling_params(&traces);
        let error = model
            .generate(&prefix, &[], None, 0, &params, 0)
            .unwrap_err();
        let message = error.to_string();
        assert!(message.contains("no audio generated"), "{message}");
    }
}

#[test]
fn prompt_building_matches_the_reference() {
    let traces = read_json(&testdata("prompt/traces.json"));

    // The segment strings, both forms.
    let (prefix, suffix, target) = prompt_segments("hello there friend", None);
    assert_eq!(
        prefix,
        traces["plain"]["prefix_parts"]
            .as_array()
            .expect("parts")
            .iter()
            .map(|v| v.as_str().expect("string").to_owned())
            .collect::<Vec<_>>()
    );
    assert!(suffix.is_empty());
    assert_eq!(target, "hello there friend");

    let reference_text = "a calm voice speaks slowly";
    let (prefix, suffix, target) = prompt_segments("hello there friend", Some(reference_text));
    assert_eq!(
        prefix,
        traces["voice"]["prefix_parts"]
            .as_array()
            .expect("parts")
            .iter()
            .map(|v| v.as_str().expect("string").to_owned())
            .collect::<Vec<_>>()
    );
    assert_eq!(
        suffix,
        traces["voice"]["suffix_parts"]
            .as_array()
            .expect("parts")
            .iter()
            .map(|v| v.as_str().expect("string").to_owned())
            .collect::<Vec<_>>()
    );
    assert_eq!(target, "hello there friend");

    // The prepared grids, exact ints.
    let model = open_model("pure_attention");
    let config = model.config.clone();
    let plain_prefix = i32_vec(&traces["plain"]["prefix_ids"]);
    let (grid, mask) = prepare_prompt(&config, &plain_prefix, &[], None, 0);
    assert_eq!(grid, i32_rows(&traces["plain"]["grid"]));
    assert_eq!(
        mask,
        traces["plain"]["mask"]
            .as_array()
            .expect("mask")
            .iter()
            .map(|v| v.as_i64().expect("m") != 0)
            .collect::<Vec<_>>()
    );

    let voice_prefix = i32_vec(&traces["voice"]["prefix_ids"]);
    let voice_suffix = i32_vec(&traces["voice"]["suffix_ids"]);
    let reference_codes = i32_rows(&traces["voice"]["reference_codes"]);
    let (grid, mask) = prepare_prompt(
        &config,
        &voice_prefix,
        &voice_suffix,
        Some(&reference_codes),
        traces["voice"]["reference_length"].as_u64().expect("len") as usize,
    );
    assert_eq!(grid, i32_rows(&traces["voice"]["grid"]));
    assert_eq!(
        mask,
        traces["voice"]["mask"]
            .as_array()
            .expect("mask")
            .iter()
            .map(|v| v.as_i64().expect("m") != 0)
            .collect::<Vec<_>>()
    );
    // The semantic row carries the offset codes; book column 1 carries the
    // semantic book raw (the reference writes codes row-by-row).
    let begin = config.semantic_begin_id as i32;
    let width = voice_prefix.len();
    assert_eq!(
        grid[0][width..width + 2],
        [reference_codes[0][0] + begin, reference_codes[0][1] + begin]
    );
    assert_eq!(grid[1][width..width + 2], reference_codes[0][..2]);
    assert_eq!(grid[2][width..width + 2], reference_codes[1][..2]);
}

#[test]
fn prompt_segments_recognizes_every_speaker_tag_form() {
    // The reference keeps an existing <|speaker:N|> tag for any N and
    // prepends <|speaker:0|> otherwise.
    let (prefix, _, _) = prompt_segments("hi", Some("<|speaker:2|>a voice"));
    assert!(prefix[2].contains("<|speaker:2|>a voice"), "{prefix:?}");
    let (prefix, _, _) = prompt_segments("hi", Some("<|speaker:0|>a voice"));
    assert!(prefix[2].contains("<|speaker:0|>a voice"), "{prefix:?}");
    let (prefix, _, _) = prompt_segments("hi", Some("a voice"));
    assert!(prefix[2].contains("<|speaker:0|>a voice"), "{prefix:?}");
    // Whitespace of the reference text is normalized like _clean_text; the
    // target lives in the suffix's user turn (index 2 of 5 parts).
    let (_, suffix, target) = prompt_segments("  spaced   out  ", Some("ref"));
    assert_eq!(target, "spaced out");
    assert!(suffix[2].ends_with("spaced out"), "{suffix:?}");
}

#[test]
fn legacy_top_k_top_p_matches_the_reference_on_fixed_logits() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let Some(filtered) = case["filtered"].as_array() else {
            continue;
        };
        let logits = f32_vec_masked(&case["logits"]);
        let want = f32_vec_masked(&Value::Array(filtered.clone()));
        let got = legacy_top_k_top_p(
            &logits,
            case["top_k"].as_u64().expect("top_k") as usize,
            case["top_p"].as_f64().expect("top_p") as f32,
        );
        assert_kept_pattern_and_values(
            &got,
            &want,
            SAMPLER_TOLERANCE,
            case["name"].as_str().expect("name"),
        );
    }
}

#[test]
fn exponential_race_matches_the_reference_on_fixed_uniforms() {
    let traces = read_json(&testdata("sampling/traces.json"));
    for case in traces["cases"].as_array().expect("cases") {
        let Some(scores_value) = case["scores"].as_array() else {
            continue;
        };
        let scores = f32_vec_masked(&Value::Array(scores_value.clone()));
        let uniforms = f32_vec(&case["uniforms"]);
        let winner = super::exponential_race(&scores, &uniforms);
        assert_eq!(
            winner as usize,
            case["winner"].as_u64().expect("winner") as usize,
            "race case {}",
            case["name"].as_str().expect("name")
        );
    }
}

#[test]
fn ras_switching_matches_the_reference_decision_rules() {
    let traces = read_json(&testdata("sampling/traces.json"));
    let case = traces["cases"]
        .as_array()
        .expect("cases")
        .iter()
        .find(|c| c["name"] == "ras_switch")
        .expect("ras switch case");
    let filtered = f32_vec_masked(&case["filtered_logits"]);
    let uniforms_normal = f32_vec(&case["uniforms_normal"]);
    let uniforms_high = f32_vec(&case["uniforms_high"]);
    let mut config = open_model("pure_attention").config;
    let params = SamplingParams {
        max_new_tokens: 1,
        temperature: 0.7,
        top_p: 0.9,
        top_k: 50,
        do_sample: true,
    };

    let run = |previous: Option<&[i32]>| {
        let mut uniforms = Uniforms::new(0);
        uniforms.push(&uniforms_normal);
        uniforms.push(&uniforms_high);
        sample_semantic(&config, &filtered, &params, previous, &mut uniforms)
    };

    let windows = case["windows"].as_object().expect("windows");
    for (name, window) in windows {
        let chosen = match window["previous"].as_array() {
            Some(previous) => {
                let previous: Vec<i32> = previous
                    .iter()
                    .map(|v| v.as_i64().expect("id") as i32)
                    .collect();
                run(Some(&previous))
            }
            None => run(None),
        };
        assert_eq!(
            chosen as usize,
            window["chosen"].as_u64().expect("chosen") as usize,
            "ras window {name}"
        );
    }

    // The falcon rule: a repeated pick below codebook_size is semantic and
    // switches; EOS (codebook_size) never switches.
    config.slow_backbone = "falcon_h1".to_owned();
    // Compact logits: width codebook_size + 1, eos at codebook_size.
    let vocab = config.codebook_size + 1;
    let mut compact = vec![f32::NEG_INFINITY; vocab];
    for (id, slot) in compact.iter_mut().enumerate().take(config.codebook_size) {
        *slot = (id as f32) * 0.05;
    }
    compact[config.codebook_size] = 8.0; // eos dominates both races
    let mut eos_uniforms = Uniforms::new(0);
    eos_uniforms.push(&vec![0.5; vocab]);
    eos_uniforms.push(&vec![0.5; vocab]);
    let eos_pick = sample_semantic(
        &config,
        &compact,
        &params,
        Some(&[config.codebook_size as i32; 4]),
        &mut eos_uniforms,
    );
    assert_eq!(eos_pick, config.codebook_size as i32, "falcon eos repeat");

    // A repeated semantic switches when the two draws disagree: code 1
    // dominates, the normal uniforms favor it, the ras uniforms favor
    // code 2.
    // Three candidates so the ras_top_p 0.9 filter keeps 1 and 2 (their
    // cumulative softmax stays under 0.9) while dropping 3.
    let mut compact = vec![f32::NEG_INFINITY; vocab];
    compact[1] = 6.0;
    compact[2] = 5.9;
    compact[3] = 5.8;
    let normal_uniforms = {
        let mut u = vec![0.5; vocab];
        u[1] = 0.9;
        u[2] = 0.2;
        u
    };
    let high_uniforms = {
        let mut u = vec![0.5; vocab];
        u[1] = 0.2;
        u[2] = 0.9;
        u
    };
    let mut repeated = vec![0i32; config.ras_window_size];
    repeated[config.ras_window_size - 1] = 1;
    let mut switch_uniforms = Uniforms::new(0);
    switch_uniforms.push(&normal_uniforms);
    switch_uniforms.push(&high_uniforms);
    let switched = sample_semantic(
        &config,
        &compact,
        &params,
        Some(&repeated),
        &mut switch_uniforms,
    );
    assert_eq!(
        switched, 2,
        "the repeated semantic switches to the ras draw"
    );
    let clean = vec![0i32; config.ras_window_size];
    let mut clean_uniforms = Uniforms::new(0);
    clean_uniforms.push(&normal_uniforms);
    clean_uniforms.push(&high_uniforms);
    let unswitched = sample_semantic(
        &config,
        &compact,
        &params,
        Some(&clean),
        &mut clean_uniforms,
    );
    assert_eq!(unswitched, 1, "no repeat keeps the normal draw");
}

#[test]
fn greedy_semantic_picks_stay_inside_the_semantic_range() {
    // The pure-attention filter keeps only [begin, end] and EOS; a greedy
    // run must never emit anything else (regression for the filter chain
    // order: legacy top-k/top-p BEFORE temperature).
    let traces = read_json(&testdata("pure_attention/traces.json"));
    let model = open_model("pure_attention");
    let codes = i32_rows(&traces["codes"]);
    for row in &codes {
        for &code in row {
            assert!(
                (0..model.config.codebook_size as i32).contains(&code),
                "code {code}"
            );
        }
    }
}
